
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_tpss_gaussian_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_tpss_gaussian", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.312697210701362e-02, -5.260650755536039e-02, -5.184951022873611e-02, -5.074268151424859e-02, -4.911155020356299e-02, -4.667944198321562e-02, -4.299286981556880e-02, -3.730498085945024e-02, -2.861346549907579e-02, -1.733966325445157e-02, -1.103969189189111e-02, -3.773904919867684e-02, -4.583935859873151e-02, -3.246250032752844e-02, -1.782131862586089e-02, -4.651927901181015e-03, -2.361981509928097e-04, -8.629033055279262e-07, -2.425561572817381e-10, -2.887287395820188e-15]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


